"{0} написан на Go и на роутере с малым ОЗУ может разрастаться до нехватки памяти — частая причина внезапной перезагрузки. Лимит (GOGC/GOMEMLIMIT) удерживает потребление в рамках. Применяется при следующем {1}.": "{0} is written in Go and on a router with little RAM it can grow until memory runs out — a common cause of sudden reboots. The limit (GOGC/GOMEMLIMIT) keeps usage in check. Applied on the next {1}.",
