". Если прошивка поддерживает модуль, можно поставить": ". If the firmware supports the module, you can install",
"и загрузить": "and load",
"— но на части прошивок (напр. Keenetic) ни пакета, ни": "— but on some firmwares (e.g. Keenetic) there is neither the package nor",
