"Переподключать при плохом соединении": "Reconnect on a bad connection",
"Следит за туннелем и автоматически перезапускает его при зависании. Ловит четыре случая:": "Watches the tunnel and restarts it automatically when it hangs. Catches four cases:",
"трафик стоит": "traffic stalled",
"— с подъёма не принято ни байта, хотя туннель шлёт; handshake устарел; туннель": "— not a single byte received since it came up although the tunnel sends; handshake is stale; the tunnel",
"шлёт, но не принимает": "sends but does not receive",
"(данные встали, хотя handshake ещё «свежий» — частая причина «сайты тормозят, потом сеть отваливается»); активная проба не проходит. Детектор «приём встал» работает по счётчикам самого демона — без лишнего трафика. Дополнительно: если туннель с": "(data stalled although the handshake is still “fresh” — a common cause of “sites slow down, then the network drops”); the active probe fails. The “receive stalled” detector works on the daemon's own counters — without extra traffic. Additionally: if a tunnel with",
"автозапуском": "autostart",
"совсем упал (демон/интерфейс умер) — поднимает его заново. PersistentKeepalive = 25 теперь проставляется новым конфигам автоматически (держит NAT-binding живым, чтобы зависание ловилось и в простое).": "went down completely (daemon/interface died), it brings it up again. PersistentKeepalive = 25 is now set for new configs automatically (keeps the NAT binding alive so that hangs are caught when idle too).",
