"Двойной туннель: трафик заходит во": "Double tunnel: traffic enters",
"(внутренний WARP), а UDP самого inner'а до Cloudflare идёт внутри": "(the inner WARP), and the inner's own UDP to Cloudflare goes inside",
"(внешний WARP, наружу через WAN). Провайдер видит только outer, Cloudflare на выходе — только inner. Это помогает обойти ограничения, настроенные под одиночный WARP.": "(the outer WARP, out via WAN). The ISP sees only the outer, Cloudflare at the exit sees only the inner. This helps bypass restrictions tuned for a single WARP.",
"Как завернуть трафик в WARP-in-WARP": "How to send traffic into WARP-in-WARP",
"На вкладках «Импорт» / «Генерация» подготовьте": "On the “Import” / “Generation” tabs prepare",
"два разных": "two different",
"WARP-конфига.": "WARP configs.",
"Здесь выберите": "Here choose",
"(первый, через WAN) и": "(the first, via WAN) and",
"(второй, пойдёт внутри outer) и нажмите «Создать двойной туннель».": "(the second, goes inside the outer) and press “Create double tunnel”.",
"Связка сама поднимет оба туннеля и пропишет маршрут до endpoint'а inner через outer.": "The pair brings up both tunnels by itself and sets the route to the inner's endpoint through the outer.",
"На странице": "On the page",
"заведите маршрут с методом": "create a route with the method",
"— он подписан там «WARP-in-WARP: внутренний». Сам по себе трафик в туннели не идёт; маршрут в": "— it is labelled there “WARP-in-WARP: inner”. Traffic does not go into the tunnels by itself; a route into",
"дал бы одиночный WARP.": "would give a single WARP.",
"Отключение — кнопкой разбора связки ниже (вернёт оба туннеля в обычный режим). Связка переживает перезапуск GUI — восстанавливается автоматически.": "Disable it with the pair teardown button below (returns both tunnels to normal mode). The pair survives a GUI restart — it is restored automatically.",
