", что на вкладке «Официальный», — клонированный с правками: домены проверяются параллельно, а набрав нужное число рабочих стратегий, проверка переходит к следующему тесту или домену. В конце из находок собирается одна стратегия на все домены (профили через": " as on the “Official” tab — cloned with changes: domains are checked in parallel, and once the required number of working strategies is collected, the check moves to the next test or domain. At the end the findings are assembled into one strategy for all domains (profiles via",
"Сколько копий blockcheck2 работают одновременно. 1 — домены по очереди. На слабом роутере больше 2 не ставьте: каждая копия гоняет curl и nfqws2.": "How many blockcheck2 copies run at once. 1 — domains one after another. On a weak router don't set more than 2: each copy runs curl and nfqws2.",
"Одновременно доменов": "Domains at once",
"1 (по очереди)": "1 (one after another)",
"Набрав столько рабочих стратегий на тест (все попытки успешны), blockcheck2 бросает оставшиеся варианты этого теста. 0 — перебрать всё, как оригинал.": "After collecting this many working strategies per test (all attempts successful), blockcheck2 drops the remaining variants of this test. 0 — try everything, like the original.",
"Хватит рабочих на тест": "Enough working per test",
"все (без остановки)": "all (no stop)",
"REPEATS: столько попыток на стратегию; рабочая — успешны все. 3 → успешность 3/3.": "REPEATS: this many attempts per strategy; working means all succeed. 3 → success rate 3/3.",
"Попыток (REPEATS)": "Attempts (REPEATS)",
"IP-версия": "IP version",
"Протоколы": "Protocols",
"Пока идёт проверка, обход GUI (nfqws2 и правила перехвата) снят, после — возвращается как было. Иначе проверка шла бы поверх уже работающей стратегии.": "While the check runs, the GUI bypass (nfqws2 and interception rules) is removed, afterwards it is restored as it was. Otherwise the check would run on top of an already working strategy.",
"Снять обход на время проверки": "Remove the bypass during the check",
"Перехват blockcheck2 матчит по IP: две копии на одном адресе делили бы трафик. Такие домены проверяются одной копией по очереди.": "blockcheck2 interception matches by IP: two copies on one address would share traffic. Such domains are checked by one copy in turn.",
"Домены с общими IP — одной копией": "Domains with shared IPs — one copy",
"CURL_HTTPS_GET=1 — качать тело (GET), а не заголовки: ловит обрыв на ~16-20 КБ.": "CURL_HTTPS_GET=1 — download the body (GET), not headers: catches a cut at ~16-20 KB.",
