"Текст для вопроса в чате или issue: версии, состояние, списки, журнал. Без паролей, токенов и внешнего адреса": "Text for a question in a chat or an issue: versions, state, lists, log. No passwords, tokens or external address",
"Отчёт для помощи": "Report for help",
"Быстрый ремонт": "Quick repair",
"Поломки, которые выглядят как «обход не работает», но DPI тут ни при чём: сбитые часы (TLS падает на сертификатах, подбор показывает 0%), упавший DNS роутера, пропавший маршрут в интернет.": "Breakages that look like “bypass doesn't work” but have nothing to do with DPI: a wrong clock (TLS fails on certificates, search shows 0%), the router's DNS is down, the internet route is missing.",
"Проверить снова": "Check again",
"Утечки IP и DNS": "IP and DNS leaks",
"Внешний IP напрямую и через каждый туннель (тот же IP — трафик идёт мимо туннеля) и какие DNS-серверы видит мир, когда роутер резолвит имя. Запросы уходят на bash.ws и api.ipify.org, поэтому проверка — только по кнопке.": "External IP directly and through each tunnel (the same IP means traffic goes around the tunnel) and which DNS servers the world sees when the router resolves a name. Requests go to bash.ws and api.ipify.org, so the check runs only on the button.",
"Проверки ещё не было.": "No check yet.",
"Как клиент LAN": "As a LAN client",
"Пробы GUI идут с самого роутера, а телефон ходит другим путём: через FORWARD, правила по устройствам, transparent-режим. Здесь те же сайты открываются ещё и из временного «клиента», подключённого к мосту LAN, и видно, где расходится.": "GUI probes run from the router itself, while a phone goes another way: through FORWARD, per-device rules, transparent mode. Here the same sites are also opened from a temporary “client” attached to the LAN bridge, and you can see where things diverge.",
"сайты через пробел": "sites separated by spaces",
"адрес клиента (авто)": "client address (auto)",
"Куда пойдёт сайт": "Where the site will go",
"Почему сайт идёт не так, как настроено: hosts, DNS, маршруты единого слоя (туннель забирает трафик мимо nfqws2) и какой профиль стратегии возьмёт HTTPS, QUIC и HTTP — и почему пропущены остальные.": "Why a site goes differently than configured: hosts, DNS, unified layer routes (a tunnel takes traffic around nfqws2) and which strategy profile will take HTTPS, QUIC and HTTP — and why the others are skipped.",
"Вставьте этот текст в чат или issue. В нём нет паролей, токенов, внешнего адреса и содержимого списков. Сам отчёт никуда не отправляется — его копируете вы.": "Paste this text into a chat or an issue. It contains no passwords, tokens, external address or list contents. The report itself is not sent anywhere — you copy it.",
"Показать имена сайтов (по умолчанию скрыты)": "Show site names (hidden by default)",
"Собираю…": "Collecting…",
"Скопировать": "Copy",
"Самодиагностика zapret-gui": "zapret-gui self-check",
"Полная проверка прямо на этом устройстве: зависимости (python-модули, системные утилиты), движки (zapret2/AWG/sing-box/mihomo), доп. туннели и прокси (WARP/MASQUE, WARP-in-WARP, Telegram, Opera), конфигурация и прогон юнит-тестов. Все результаты пишутся в": "A full check right on this device: dependencies (python modules, system utilities), engines (zapret2/AWG/sing-box/mihomo), extra tunnels and proxies (WARP/MASQUE, WARP-in-WARP, Telegram, Opera), configuration and a unit test run. All results are written to the",
"лог": "log",
"(предупреждения — и в сохранённый лог).": "(warnings also to the saved log).",
"с юнит-тестами (на роутере — несколько минут)": "with unit tests (several minutes on a router)",
"Из консоли (работает, даже когда GUI не стартует — например, без bottle):": "From the console (works even when the GUI doesn't start — e.g. without bottle):",
