"Идёт установка:": "Installing:",
"На OpenWrt модуль NFQUEUE (": "On OpenWrt the NFQUEUE module (",
") не входит в прошивку по умолчанию — без него nfqws2 завершается сразу после запуска (exit 1). Нажмите кнопку — нужные модули ядра поставятся автоматически (нужен интернет), консоль не требуется.": ") is not part of the default firmware — without it nfqws2 exits right after start (exit 1). Press the button — the required kernel modules will be installed automatically (internet needed), no console required.",
"Будет выполнено ({0}):": "Will run ({0}):",
"Команда:": "Command:",
"Модуль NFQUEUE недоступен — обход не заработает": "The NFQUEUE module is unavailable — bypass won't work",
"Пакеты установлены, но NFQUEUE ещё не активен — обычно помогает перезагрузка роутера.": "Packages are installed, but NFQUEUE is not active yet — a router reboot usually helps.",
"Установка не удалась — см. вывод ниже и лог.": "Installation failed — see the output below and the log.",
"Не удалось получить данные о конфликтах — попробуйте «Обновить».": "Could not get conflict data — try “Refresh”.",
"Обнаружены сторонние процессы, которые могут конфликтовать:": "Third-party processes that may conflict were found:",
"Два процесса на одной очереди NFQUEUE обрабатывают пакеты по очереди и мешают друг другу: стратегия работает через раз или не работает вовсе. Обычно это второй установщик zapret (свой init-скрипт) — остановите его, либо разведите номера очередей.": "Two processes on the same NFQUEUE queue process packets in turns and interfere with each other: the strategy works every other time or not at all. Usually it is a second zapret installer (with its own init script) — stop it, or use different queue numbers.",
"Посторонних процессов nfqws/tpws нет — очередь NFQUEUE наша.": "No foreign nfqws/tpws processes — the NFQUEUE queue is ours.",
"Ещё {0} процесс(ов) nfqws запущено нашим подбором стратегии (blockcheck/сканер) — это не конфликт, они исчезнут вместе с проверкой.": "{0} more nfqws process(es) were started by our strategy search (blockcheck/scanner) — this is not a conflict, they will go away with the check.",
"конфликт": "conflict",
"возможен конфликт": "possible conflict",
"замечено": "noticed",
"Другие обходчики и системы маршрутизации (обходчики DPI спорят с nfqws2 за пакеты, остальные — с единым слоем и прозрачным проксированием):": "Other bypass tools and routing systems (DPI bypass tools compete with nfqws2 for packets, the rest — with the unified layer and transparent proxying):",
"Сторонних систем обхода (getdomains, XKeen, podkop, Xray, redsocks) не найдено.": "No third-party bypass systems (getdomains, XKeen, podkop, Xray, redsocks) found.",
"Здесь ищутся два вида помех: посторонние процессы": "Two kinds of interference are looked for here: foreign processes",
"на той же очереди NFQUEUE и установленные рядом системы обхода — они переписывают те же правила firewall и маршрутизации, что и мы. Пусто в обоих блоках — значит, наш слой ни с чем не делит систему.": "on the same NFQUEUE queue and bypass systems installed alongside — they rewrite the same firewall and routing rules as we do. Both blocks empty means our layer shares the system with nothing.",
