"Спрашивать адрес выбранных сайтов не у провайдера, а у другого DNS-сервера. Помогает, когда провайдер подменяет ответ DNS (сайт резолвится в заглушку или не резолвится).": "Ask another DNS server, not the ISP's, for the address of selected sites. Helps when the ISP spoofs the DNS answer (the site resolves to a stub or doesn't resolve).",
"Добавить правило": "Add rule",
"Домен, например youtube.com": "Domain, e.g. youtube.com",
"— загрузка...": "— loading...",
"Быстро через Cloudflare:": "Quickly via Cloudflare:",
"Поддомены входят в правило автоматически. Запрос уходит обычным DNS (порт 53) на выбранный сервер: если провайдер перехватывает весь DNS, это не поможет — тогда сайт нужно пустить через туннель (раздел «Маршрутизация»).": "Subdomains are included in the rule automatically. The query goes as plain DNS (port 53) to the selected server: if the ISP intercepts all DNS, this won't help — then the site needs to go through a tunnel (the “Routing” section).",
"Правила": "Rules",
"Записать правила в dnsmasq ещё раз": "Write the rules to dnsmasq again",
"Применить заново": "Re-apply",
"Замер DNS-серверов": "DNS server benchmark",
"Замерить": "Measure",
"Замерить и сделать лучший сервером «Авто»": "Measure and make the best one the “Auto” server",
"Выбрать лучший": "Choose the best",
"Задержка и доля ответов каждого сервера с роутера. Главное — UDP: им dnsmasq ходит по правилам выше. «Подмена» — провайдер перехватывает UDP к этому серверу и отдаёт заглушку для заблокированного сайта. Сервер «Авто» в правилах — лучший по замеру; пока такие правила есть, замер повторяется раз в сутки.": "Latency and answer rate of each server from the router. UDP matters most: dnsmasq uses it for the rules above. “Spoofing” — the ISP intercepts UDP to this server and returns a stub for a blocked site. The “Auto” server in rules is the best by measurement; while such rules exist, the measurement repeats once a day.",
