"Сейчас: {0} — уже в ОЗУ.": "Now: {0} — already in RAM.",
"Сейчас: {0} — на постоянном носителе. Действует со следующего запуска туннеля; после перезагрузки логи пропадают.": "Now: {0} — on persistent storage. Takes effect from the next tunnel start; logs are lost after a reboot.",
"Журнал критичных событий на flash": "Critical events log on flash",
"Переживает перезагрузку — помогает понять, почему роутер перезагрузился. Пишет немного.": "Survives a reboot — helps understand why the router rebooted. Writes little.",
"Что в него писать": "What to write to it",
"предупреждения и ошибки": "warnings and errors",
"только ошибки": "errors only",
"История изменений файлов": "File change history",
"Копия настроек и списков при каждом сохранении (для отката). Пишет только когда вы что-то меняете.": "A copy of settings and lists on every save (for rollback). Writes only when you change something.",
"Счётчики трафика прокси — на диск не чаще, сек": "Proxy traffic counters — to disk at most every, sec",
"Опрос идёт каждые 2 с; при сбое питания теряется не больше этого интервала.": "Polling runs every 2 s; on a power failure no more than this interval is lost.",
"Статистика этого раздела — на flash раз в, ч": "This section's statistics — to flash every, h",
"0 — только в ОЗУ: после перезагрузки учёт начнётся заново.": "0 — RAM only: tracking starts over after a reboot.",
"Отложенная запись: держать изменения в ОЗУ дольше": "Delayed writes: keep changes in RAM longer",
"Повторные записи одного блока сливаются в одну. Сейчас ядро: dirty_expire {0}, writeback {1}.": "Repeated writes of the same block are merged into one. Kernel now: dirty_expire {0}, writeback {1}.",
"Сколько держать, сек": "How long to keep, sec",
"При внезапной пропаже питания теряется до этого времени последних изменений.": "On a sudden power loss up to this much of the latest changes is lost.",
"noatime — не записывать время доступа при чтении файлов": "noatime — don't write the access time when reading files",
"Журнал ext4: интервал, сек (0 — не менять)": "ext4 journal: interval, sec (0 — don't change)",
"У ядра 5 с. Больше — меньше записи, но дольше окно потери при сбое питания. Только для ext4.": "The kernel default is 5 s. More means fewer writes, but a longer loss window on power failure. ext4 only.",
"Ресурс NAND для оценки износа UBI, циклов (0 — авто)": "NAND endurance for UBI wear estimate, cycles (0 — auto)",
"SLC — около 100 000, MLC — около 3 000. Посмотрите в даташите чипа, если знаете модель.": "SLC — about 100,000, MLC — about 3,000. Check the chip datasheet if you know the model.",
"Готовые наборы заполняют настройки ниже — потом можно поправить любую. Ничего не применяется до «Сохранить».": "Ready-made presets fill the settings below — you can then adjust any of them. Nothing is applied until “Save”.",
