"(надёжный доменный роутинг: CDN/QUIC, чистый DNS — блокируемые домены резолвит сам прокси). Остальное идёт напрямую. OS-правила (ip rule) НЕ нужны — mihomo маршрутизирует сам. После создания запустите конфиг ниже.": "(reliable domain routing: CDN/QUIC, clean DNS — blocked domains are resolved by the proxy itself). The rest goes direct. OS rules (ip rule) are NOT needed — mihomo routes by itself. After creating, start the config below.",
