"⚠️ На Keenetic экспериментально: auto-route ставит свои маршруты (может конфликтовать с NDM); на iptables-прошивках перехват ПЕРЕсылаемого трафика LAN-устройств не гарантирован (полноценный auto-redirect — только на nftables). Если устройство за роутером не заворачивается — используйте доменный режим выше или AWG.": "⚠️ Experimental on Keenetic: auto-route installs its own routes (may conflict with NDM); on iptables firmwares interception of FORWARDED traffic of LAN devices is not guaranteed (full auto-redirect only on nftables). If a device behind the router is not redirected — use the domain mode above or AWG.",
