"Перезапускать mihomo при плохом соединении": "Restart mihomo on a bad connection",
"(external-controller: реально открывает облако сквозь активный узел группы) и перезапускает инстанс, если соединение зависло или движок перестал отвечать. Работает только для конфигов с external-controller — наш флоу маршрутизации добавляет его автоматически.": "(external-controller: actually opens the cloud through the group's active node) and restarts the instance if the connection hangs or the engine stops responding. Works only for configs with external-controller — our routing flow adds it automatically.",
