". Список ниже собран по тексту конфига и по данным запущенного движка — он может быть неполным. Проверьте конфиг кнопкой «Проверить (mihomo -t)» на странице «Инстансы».": ". The list below is built from the config text and the running engine's data — it may be incomplete. Check the config with the “Check (mihomo -t)” button on the “Instances” page.",
"Секция": "Section",
"прочитана по тексту конфига (структурный разбор ничего не дал). Редактирование списка из таблицы в таком конфиге лучше не делать — правьте YAML на странице «Инстансы».": "was read from the config text (structural parsing gave nothing). Better not to edit the list from the table in such a config — edit the YAML on the “Instances” page.",
"· обновление раз в {0} с": "· updated every {0} s",
"Из них сейчас загружено узлов:": "Of them, nodes loaded now:",
"— они показаны в таблице ниже.": "— they are shown in the table below.",
"Узлы пока не загружены. Обычно это значит, что mihomo не смог скачать подписку (нет сети, неверный URL или требуется свой User-Agent) — посмотрите «Лог».": "The nodes are not loaded yet. Usually this means mihomo could not download the subscription (no network, wrong URL or a custom User-Agent is required) — see “Log”.",
"Узлы появятся после запуска конфига: их скачивает сам mihomo, в файле конфига их нет.": "The nodes appear after the config starts: mihomo downloads them itself, they are not in the config file.",
