"Установка и обновление бинаря mihomo (Clash.Meta) из апстрим-релизов MetaCubeX/mihomo.": "Installing and updating the mihomo (Clash.Meta) binary from the upstream MetaCubeX/mihomo releases.",
"← Инстансы": "← Instances",
"Бесплатный HTTP/SOCKS5 прокси через SurfEasy VPN": "Free HTTP/SOCKS5 proxy via SurfEasy VPN",
"Хранить длинный хвост вывода opera-proxy (600 строк вместо 60)": "Keep a long tail of opera-proxy output (600 lines instead of 60)",
"режим отладки": "debug mode",
"Логи прокси видны по кнопке «Лог». Подробные строки появятся, только если в настройках выбран": "Proxy logs are visible with the “Log” button. Detailed lines appear only if the settings select",
"— уровень задаёт сам opera-proxy, а режим отладки лишь увеличивает хранимый хвост.": "— the level is set by opera-proxy itself, debug mode only increases the stored tail.",
"Использование": "Usage",
"Opera Proxy создаёт HTTP прокси на": "Opera Proxy creates an HTTP proxy on",
". Настройте приложения использовать этот прокси.": ". Configure applications to use this proxy.",
"Отдельным методом в «Маршрутизации» его выбрать нельзя: там цель правила — сетевой интерфейс, а Opera Proxy даёт только локальный порт. Чтобы заворачивать в неё трафик роутера, подключите её как upstream внутрь sing-box или mihomo — правило маршрутизации тогда обычное, на TUN этого движка.": "It can't be chosen as a separate method in “Routing”: there the rule target is a network interface, and Opera Proxy provides only a local port. To send router traffic into it, attach it as an upstream inside sing-box or mihomo — the routing rule is then a regular one, on that engine's TUN.",
"Подключить в": "Attach to",
"Добавить в конфиг": "Add to config",
"В конфиг добавится прокси с текущим bind и режимом (HTTP или SOCKS5 — как выбрано в настройках выше), плюс правило «": "A proxy with the current bind and mode (HTTP or SOCKS5 — as selected in the settings above) is added to the config, plus a rule “",
"— напрямую»: без него трафик самой Opera уходил бы в туннель по кругу. Дальше в конфиге движка направьте на этот прокси нужные домены — сам по себе он трафик не забирает.": "— direct”: without it Opera's own traffic would loop into the tunnel. Then, in the engine config, point the needed domains to this proxy — by itself it doesn't take any traffic.",
