"Не открывается сайт? Проверить по шагам цепочку каждого маршрута: интерфейс, правила ядра, наборы адресов, сам туннель — и показать, где она рвётся.": "A site doesn't open? Check each route's chain step by step: interface, kernel rules, address sets, the tunnel itself — and show where it breaks.",
