"Переприменить все маршруты заново и снять из ядра правила/наборы, за которыми уже не стоит ни одного маршрута. Пригодится, когда туннелю поменяли AllowedIPs или он переподнялся, а маршрутизация осталась в старом состоянии.": "Re-apply all routes and remove from the kernel the rules/sets that no route uses any more. Useful when a tunnel's AllowedIPs changed or it came back up while routing stayed in the old state.",
