"Включён: пока туннель лежит, трафик маршрутов не уходит в обход туннеля, а дропается.": "On: while the tunnel is down, route traffic doesn't go around the tunnel but is dropped.",
"Выключен: пока туннель перезапускается, трафик маршрутов на несколько секунд уходит через провайдера.": "Off: while the tunnel restarts, route traffic goes through the ISP for a few seconds.",
"Проверка доступности {0}": "Reachability check {0}",
"Роутер в фоне открывает сайты маршрутов с включённой проверкой и показывает, работают ли они. Нужна для автопереключения на запасной путь.": "The router opens route sites with the check enabled in the background and shows whether they work. Needed for automatic switching to the backup path.",
