"Рабочая точка туннелей и маршрутов": "Working point of tunnels and routes",
"После правки конфига туннеля или маршрута роутер ждёт {0} мин и проверяет сайты мониторинга. Ничего не потерялось — состояние становится рабочим; потерялось — уведомит и предложит вернуть.": "After a tunnel config or route edit the router waits {0} min and checks the monitoring sites. Nothing lost — the state becomes the working one; something lost — it notifies and offers to restore.",
"Возвращать самому, если правка сломала сайты": "Restore by itself if an edit broke sites",
"Вернуть конфиги туннелей и маршруты к рабочей точке? Изменённые конфиги перезапишутся, поднятые туннели перезапустятся, удалённые после неё вернутся. Конфиги, добавленные после, останутся.": "Restore tunnel configs and routes to the working point? Changed configs will be overwritten, running tunnels restarted, those deleted after it come back. Configs added after it stay.",
