"Локальный режим": "Local mode",
"({0}): правила применяются к исходящему трафику этой машины — LAN-форвардинг не используется, выбор устройств сети обычно не нужен. {1}": "({0}): rules apply to this machine's outgoing traffic — LAN forwarding is not used, choosing network devices is usually not needed. {1}",
