"… ещё {0}": "… {0} more",
"Найдены правила старого формата ({0})": "Old-format rules found ({0})",
"Это правила прежнего раздела «AWG-правила» (отдельное хранилище). Теперь маршрутизация единая — перенесите их в маршруты одним нажатием: каждое правило станет маршрутом с методом-туннелем, ничего не потеряется. Перенос также выполняется автоматически при перезапуске GUI.": "These are rules of the former “AWG rules” section (a separate store). Routing is now unified — migrate them into routes with one click: each rule becomes a route with a tunnel method, nothing is lost. Migration also happens automatically on GUI restart.",
"Перенести в единый слой": "Migrate to the unified layer",
"· запросов: {0} (TCP: {1}), совпало: {2}, IP добавлено: {3}, AAAA вырезано: {4}": "· queries: {0} (TCP: {1}), matched: {2}, IPs added: {3}, AAAA stripped: {4}",
"Туннели WARP/AWG часто без IPv6: получив IPv6-адрес домена из маршрута, клиент пойдёт по IPv6 мимо туннеля. Вырезание AAAA оставляет ему только IPv4 — и трафик идёт в туннель.": "WARP/AWG tunnels often have no IPv6: having received a domain's IPv6 address from a route, the client will go over IPv6 around the tunnel. Stripping AAAA leaves it only IPv4 — and the traffic goes into the tunnel.",
"IPv6 доменов маршрутов: вырезать": "IPv6 of route domains: strip",
"IPv6 доменов маршрутов: отдавать": "IPv6 of route domains: return",
"включён (порт {0})": "on (port {0})",
"включён (порт": "on (port",
"Выключить DNS-перехват": "Disable DNS interception",
"Включить DNS-перехват": "Enable DNS interception",
"DNS-перехват:": "DNS interception:",
"Перехватывать DNS-запросы LAN-клиентов (udp:53 → встроенный прокси поверх штатного резолвера). IP доменов из маршрутов попадают в маршрутизацию в момент запроса клиента — включая CDN-поддомены, как с dnsmasq. Клиенты с включённым DoH перехвату не видны.": "Intercept DNS queries of LAN clients (udp:53 → a built-in proxy on top of the stock resolver). IPs of route domains get into routing at the moment of the client's query — including CDN subdomains, as with dnsmasq. Clients with DoH enabled are invisible to interception.",
"IPv6-адреса доменов маршрутов отдаются": "IPv6 addresses of route domains are returned",
"IPv6-адреса доменов маршрутов вырезаются": "IPv6 addresses of route domains are stripped",
"Выключить kill-switch": "Disable kill-switch",
"Включить kill-switch": "Enable kill-switch",
"Держать в таблице маршрутизации blackhole-маршрут. Пока туннель поднят, он проигрывает настоящему по метрике и ни на что не влияет; как только туннель упал — трафик маршрутов дропается вместо того, чтобы уйти мимо туннеля через провайдера.": "Keep a blackhole route in the routing table. While the tunnel is up it loses to the real one by metric and affects nothing; as soon as the tunnel goes down, route traffic is dropped instead of going around the tunnel through the ISP.",
"Платформа: {0}, firewall: {1}": "Platform: {0}, firewall: {1}",
"Настроить dnsmasq автоматически": "Configure dnsmasq automatically",
"Применить обновления dnsmasq-конфига": "Apply dnsmasq config updates",
"Откатить изменения: вернуть systemd-resolved на :53 и остановить dnsmasq": "Roll back: return systemd-resolved to :53 and stop dnsmasq",
"Откатить настройку dnsmasq": "Roll back the dnsmasq setup",
"dnsmasq не сможет прочитать файл правил": "dnsmasq won't be able to read the rules file",
"На OpenWrt dnsmasq запускается в изолированном окружении (ujail) и видит только разрешённые пути.": "On OpenWrt dnsmasq runs in an isolated environment (ujail) and sees only allowed paths.",
"подключён в": "is included in",
", но внутрь ujail не прокинут — при следующем перезапуске dnsmasq не поднимется и утащит за собой DHCP и DNS роутера. Нажмите «Применить обновления dnsmasq-конфига»: путь добавится в": ", but not passed into the ujail — on the next restart dnsmasq won't come up and will take the router's DHCP and DNS down with it. Press “Apply dnsmasq config updates”: the path will be added to",
"секции": "of the section",
"файла": "of the file",
"есть": "present",
"Маршрутизация по доменам через туннель требует dnsmasq или DNS-перехвата": "Routing domains through a tunnel requires dnsmasq or DNS interception",
