", запущен=": ", running=",
"Keenetic-native (NDMS {0}) — встроенный": "Keenetic-native (NDMS {0}) — the built-in",
"для нативных интерфейсов; для туннелей AWG/WARP/sing-box/mihomo — DNS-перехват.": "for native interfaces; for AWG/WARP/sing-box/mihomo tunnels — DNS interception.",
"— настроен через GUI": "— configured via the GUI",
"(запущен), бэкенд": "(running), backend",
"DNS-перехват": "DNS interception",
"не настроено": "not configured",
"Работает DNS-перехват: IP доменов попадают в маршрутизацию в момент запроса устройства.": "DNS interception is working: domain IPs get into routing at the moment of the device's query.",
"Пока не настроено. Нужно только для маршрутов по доменам через туннель — подсети, устройства, обход DPI и «напрямую» работают и без этого.": "Not configured yet. Needed only for routing domains through a tunnel — subnets, devices, DPI bypass and “direct” work without it.",
"Доменная маршрутизация работает так: dnsmasq резолвит указанные домены и складывает их IP в ipset/nftset, а трафик к этим IP заворачивается в выбранный туннель. Без запущенного dnsmasq собирать IP по доменам нечем.": "Domain routing works like this: dnsmasq resolves the specified domains and puts their IPs into an ipset/nftset, and traffic to these IPs is redirected into the chosen tunnel. Without a running dnsmasq there is nothing to collect IPs by domain with.",
"На": "On",
"dnsmasq — штатный DNS-сервер роутера и обычно уже слушает :53. Кнопка ниже просто убедится, что он запущен, и добавит include с нашими правилами в его конфиг.": "dnsmasq is the router's standard DNS server and usually already listens on :53. The button below will just make sure it is running and add an include with our rules to its config.",
"На десктопном Linux (Debian/Ubuntu) порт 53 обычно занят stub-listener'ом systemd-resolved, и dnsmasq не стартует. Кнопка ниже отключит DNSStubListener в": "On desktop Linux (Debian/Ubuntu) port 53 is usually taken by the systemd-resolved stub listener, and dnsmasq doesn't start. The button below will disable DNSStubListener in",
", поднимет dnsmasq на :53 и сохранит state-файл для отката.": ", bring dnsmasq up on :53 and save a state file for rollback.",
"Маршрутов пока нет": "No routes yet",
"Маршрут говорит роутеру, какой трафик куда отправлять: например, «YouTube и Telegram — через VPN, остальное — как обычно».": "A route tells the router which traffic to send where: e.g. “YouTube and Telegram — through VPN, the rest — as usual”.",
