"проверять нечего — задайте «Probe-домен» (режим эксперта), иначе проверка и автопереключение не работают": "nothing to check — set a “Probe domain” (expert mode), otherwise checking and automatic switching don't work",
"нет резервного метода: при сбое трафику некуда переключиться — добавьте резерв (хотя бы «Напрямую») и включите автопереключение": "no backup method: on failure the traffic has nowhere to switch — add a backup (at least “Direct”) and enable automatic switching",
