"<label class=\"text-muted\" style=\"padding-top:6px;\" title=\"Весь трафик с выбранных устройств локальной сети пойдёт через метод маршрута (ip rule from": "<label class=\"text-muted\" style=\"padding-top:6px;\" title=\"All traffic from the selected local network devices will go through the route method (ip rule from",
"). Работает только с туннельными методами.\"> Устройства": "). Works only with tunnel methods.\"> Devices",
"IKE/IPsec к оператору (UDP 500 и 4500) идёт напрямую: через туннель звонки по Wi-Fi обычно не поднимаются — оператор ждёт абонента из своей страны.": "IKE/IPsec to the carrier (UDP 500 and 4500) goes direct: through a tunnel Wi-Fi calls usually don't connect — the carrier expects the subscriber from its own country.",
"Wi-Fi Calling мимо туннеля (UDP 500, 4500)": "Wi-Fi Calling around the tunnel (UDP 500, 4500)",
"Порт торрент-клиента (или TorrServer) мимо туннеля: ответы входящим пирам и uTP идут напрямую и не съедают канал туннеля. Порт смотрите в настройках клиента (часто 51413 или 6881).": "The torrent client (or TorrServer) port around the tunnel: replies to incoming peers and uTP go direct and don't eat the tunnel's bandwidth. See the port in the client settings (often 51413 or 6881).",
"Порт торрент-клиента мимо туннеля:": "Torrent client port around the tunnel:",
"51413 или 6881-6889": "51413 or 6881-6889",
