"🖥 Локальный режим (ПК без LAN-клиентов): устройства обычно не нужны — домены/CIDR-правила и так действуют на трафик этой машины.": "🖥 Local mode (PC without LAN clients): devices are usually not needed — domain/CIDR rules already act on this machine's traffic.",
"IP или подсеть: 192.168.1.50 / 192.168.1.0/24": "IP or subnet: 192.168.1.50 / 192.168.1.0/24",
