"Артефакты без единого стоящего за ними маршрута ({0}): {1} Снимет кнопка «Переприменить и сбросить лишнее».": "Artifacts with no route behind them ({0}): {1} The “Re-apply and clean up leftovers” button removes them.",
"Артефакты без единого стоящего за ними маршрута": "Artifacts with no route behind them",
"Снимет кнопка «Переприменить и сбросить лишнее».": "The “Re-apply and clean up leftovers” button removes them.",
