"Проверка: STUN-запрос по UDP — так работает голосовая связь. Для голоса Discord подбирайте UDP, для самого сайта — TCP.": "Check: a STUN request over UDP — this is how voice calls work. For Discord voice search with UDP, for the site itself — TCP.",
"Проверка: QUIC-рукопожатие с именем сайта, как у браузера (HTTP/3). Если сайт открывается, но видео тормозит — часто дело в QUIC.": "Check: a QUIC handshake with the site name, like a browser does (HTTP/3). If the site opens but video stutters — QUIC is often the cause.",
"Проверка: скачиваем 64 КБ со speedtest-серверов Hetzner, OVH, DigitalOcean и Linode. Блокировка хостингов обычно обрывает загрузку на 16–20 КБ у всех сайтов на их адресах — поэтому стратегия подбирается для всего трафика, без списка доменов.": "Check: we download 64 KB from the Hetzner, OVH, DigitalOcean and Linode speedtest servers. A hosting block usually cuts downloads at 16–20 KB for all sites on their addresses — so the strategy is searched for all traffic, without a domain list.",
"Проверка: скачиваем 64 КБ с сайта. Блокировки часто пропускают первые 16–20 КБ и обрывают — такая стратегия не засчитывается.": "Check: we download 64 KB from the site. Blocks often let the first 16–20 KB through and cut — such a strategy doesn't count.",
