"Перебор остановлен досрочно — можно «Искать дальше».": "The iteration stopped early — you can “Search further”.",
"Убрать лишние шаги и повторы у лучшей рабочей: меньше нагрузки, меньше поводов сломаться": "Remove extra steps and repeats from the best working one: less load, fewer reasons to break",
