"Токен удалён": "Token deleted",
"Полный бэкап: настройки, пользовательские стратегии, конфиги sing-box/mihomo и hostlist'ы — в один JSON-файл. Удобно при переустановке или переносе на другой роутер.": "Full backup: settings, user strategies, sing-box/mihomo configs and hostlists — into one JSON file. Handy when reinstalling or moving to another router.",
