"Выбрать файл бэкапа…": "Choose a backup file…",
"Назначение ролей сетевым интерфейсам": "Assigning roles to network interfaces",
"WAN — внешний интерфейс (в сторону провайдера), LAN — локальная сеть. Кликните на бейджи WAN / WAN6 / LAN для назначения роли. Соответствует IFACE_WAN, IFACE_WAN6, IFACE_LAN в конфиге zapret2.": "WAN is the external interface (towards the ISP), LAN is the local network. Click the WAN / WAN6 / LAN badges to assign a role. Corresponds to IFACE_WAN, IFACE_WAN6, IFACE_LAN in the zapret2 config.",
"Определить WAN/WAN6/LAN по таблице маршрутов": "Detect WAN/WAN6/LAN from the routing table",
