"м": "m",
"Самый быстрый. VPN-туннель с маскировкой от блокировок. Подходит для бесплатного WARP и Proton.": "The fastest. A VPN tunnel with anti-blocking masking. Suitable for free WARP and Proton.",
"если WireGuard режут": "if WireGuard is cut",
"Бесплатный Cloudflare WARP, который выглядит как обычный HTTPS. Работает там, где не работает остальное.": "Free Cloudflare WARP that looks like regular HTTPS. Works where the rest doesn't.",
"для своих серверов": "for your own servers",
"Если у вас есть ссылка vless://, trojan://, ss:// или подписка от VPN-сервиса. Также умеет WARP и Proton.": "If you have a vless://, trojan://, ss:// link or a subscription from a VPN service. Can also do WARP and Proton.",
"То же, что sing-box (ссылки и подписки), плюс WARP с маскировкой и WARP MASQUE.": "The same as sing-box (links and subscriptions), plus masked WARP and WARP MASQUE.",
