"Бесплатный WARP (MASQUE)": "Free WARP (MASQUE)",
"WARP под видом HTTPS — если обычный режут.": "WARP disguised as HTTPS — if the regular one is cut.",
"Бесплатный Proton VPN": "Free Proton VPN",
"Серверы в Европе, США, Японии. Выбор страны.": "Servers in Europe, the USA, Japan. Choice of country.",
