"Redirect заворачивает только TCP: HTTP/3 (QUIC, UDP/443) тех же сайтов уходит напрямую, где его режет DPI. Отклонённый QUIC браузер и приложения сразу повторяют по TCP — а он уже идёт через прокси.": "Redirect redirects only TCP: HTTP/3 (QUIC, UDP/443) of the same sites goes direct, where DPI cuts it. When QUIC is rejected, browsers and apps immediately retry over TCP — and that already goes through the proxy.",
"Отклонять QUIC (UDP/443), чтобы сайты шли по TCP через прокси": "Reject QUIC (UDP/443) so that sites go over TCP through the proxy",
"Трафик машины": "Machine traffic",
"Локальный режим: заворачивается исходящий трафик этой машины (OUTPUT). Входящие соединения (SSH/веб) и ответы на них не трогаются.": "Local mode: this machine's outgoing traffic (OUTPUT) is redirected. Incoming connections (SSH/web) and replies to them are untouched.",
"Заворачивать OUTPUT (трафик самого роутера)": "Redirect OUTPUT (the router's own traffic)",
