"Платформа nftables: DNS и трафик LAN-клиентов забираются автоматически (auto_redirect TUN).": "nftables platform: DNS and LAN clients' traffic are taken automatically (auto_redirect TUN).",
"Платформа iptables (Keenetic): при включённом перехвате правило REDIRECT :53 ставится автоматически на время работы конфига (снимается при остановке). LAN-клиенты должны ходить через роутер как шлюз.": "iptables platform (Keenetic): with interception enabled, a REDIRECT :53 rule is set automatically while the config runs (removed on stop). LAN clients must use the router as their gateway.",
"Создаёт готовый sing-box-конфиг, который заворачивает выбранные домены/подсети в ваш прокси через TUN +": "Creates a ready sing-box config that sends the selected domains/subnets into your proxy via TUN +",
"(надёжно для CDN/QUIC, без DNS-leak). Остальное идёт напрямую. После создания запустите конфиг кнопкой выше.": "(reliable for CDN/QUIC, no DNS leak). The rest goes direct. After creating, start the config with the button above.",
