". Откат — просто остановите инстанс (down).": ". To roll back, just stop the instance (down).",
"⚠️ Экспериментально на Keenetic: auto_route ставит свои маршруты (может конфликтовать с NDM); на iptables-прошивках перехват ПЕРЕсылаемого трафика LAN-устройств не гарантирован. Если устройство за роутером не заворачивается — используйте обычную выборочную маршрутизацию (gvisor) или маршрут по доменам.": "⚠️ Experimental on Keenetic: auto_route installs its own routes (may conflict with NDM); on iptables firmwares interception of FORWARDED traffic of LAN devices is not guaranteed. If a device behind the router is not redirected — use regular selective routing (gvisor) or a domain route.",
