"sing-box заберёт трафик сам.": "sing-box takes the traffic itself.",
"Перезапускать sing-box при плохом соединении": "Restart sing-box on a bad connection",
"(Clash API: реально открывает облако сквозь активный сервер) и автоматически перезапускает инстанс, если соединение зависло или движок перестал отвечать. Аналог авто-переподключения AmneziaWG. Использует clash_api — наш TUN-флоу включает его автоматически.": "(Clash API: actually opens the cloud through the active server) and automatically restarts the instance if the connection hangs or the engine stops responding. Similar to AmneziaWG auto-reconnect. Uses clash_api — our TUN flow enables it automatically.",
"sing-box — конфиги": "sing-box — configs",
