"URL можно вставить и в виде": "The URL can also be pasted as",
". Если подписка внезапно «усохла» (было 6+ серверов, пришло 1–2), прежний конфиг остаётся, а в списке появится кнопка «Принять как есть».": ". If a subscription suddenly “shrank” (there were 6+ servers, 1–2 arrived), the previous config stays, and an “Accept as is” button appears in the list.",
"(рекомендуется): sing-box сам пингует серверы и бесшовно переключается на живой с минимальной задержкой — если сервер «упал», трафик мгновенно идёт через другой, без перезапуска.": "(recommended): sing-box pings the servers itself and seamlessly switches to a live one with the lowest latency — if a server “goes down”, traffic instantly goes through another one, without a restart.",
