"Управление стратегиями desync для nfqws2": "Managing desync strategies for nfqws2",
"Вставить стратегию из буфера обмена (или Ctrl+V на странице) — откроется создание новой стратегии с профилями из буфера": "Paste a strategy from the clipboard (or Ctrl+V on the page) — creating a new strategy opens with profiles from the clipboard",
"Вставить из буфера": "Paste from clipboard",
"Импорт бандла Zapret2_AutoTuner: стратегия вместе со списками, блобами и lua. Стратегия сохраняется, но не применяется": "Import a Zapret2_AutoTuner bundle: a strategy together with lists, blobs and lua. The strategy is saved but not applied",
"Импорт бандла": "Import bundle",
"Активная стратегия": "Active strategy",
"Режим отладки nfqws2 (--debug): пер-пакетный лог в журнал — грузятся ли lua, объявлены ли блобы, матчится ли пакет цели, какие desync применяются. Применяется сразу (если nfqws2 запущен — перезапустится).": "nfqws2 debug mode (--debug): a per-packet log to the log — whether lua loads, whether blobs are declared, whether the target packet matches, which desyncs apply. Applied immediately (if nfqws2 is running, it restarts).",
"🐞 Отладка nfqws2": "🐞 nfqws2 debug",
"Открыть журнал (логи nfqws2) — там виден пер-пакетный вывод при включённой отладке": "Open the log (nfqws2 logs) — the per-packet output is visible there with debugging on",
"Журнал": "Log",
"Авто-починка (healthcheck)": "Auto-repair (healthcheck)",
"проверяет связь и обновляет circular при провалах": "checks connectivity and refreshes circular on failures",
"Когда включено, демон каждые N минут проверяет YouTube/Discord/Telegram и при N провалах подряд сбрасывает выученную circular-стратегию (чтобы nfqws2 переподобрал её для затронутого домена).": "When enabled, the daemon checks YouTube/Discord/Telegram every N minutes and after N failures in a row resets the learned circular strategy (so that nfqws2 re-picks it for the affected domain).",
"Прогнать проверку прямо сейчас (без ожидания таймера). Проверка идёт ~10–30 сек.": "Run the check right now (without waiting for the timer). The check takes ~10–30 sec.",
"Проверить сейчас": "Check now",
"Настроить: какие сайты проверять, контрольный сайт, пороги": "Configure: which sites to check, the control site, thresholds",
"Настроить": "Configure",
"Демон периодически проверяет доступность сайтов. Если сайт перестал открываться — сбрасывает «выученную» стратегию для него, и обход (circular) подберёт рабочую заново.": "The daemon periodically checks site reachability. If a site stopped opening, it resets the “learned” strategy for it, and the bypass (circular) will pick a working one again.",
"Полезно": "Useful",
", если используете авто-стратегию (circular) и хотите, чтобы обход сам восстанавливался без вашего участия. Кнопка «Проверить сейчас» работает и при выключенном демоне.": ", if you use an auto strategy (circular) and want the bypass to recover by itself without your involvement. The “Check now” button works even with the daemon off.",
