"Известные сервисы для проверки:": "Known services to check:",
"Свои сайты (по одному в строке:": "Your own sites (one per line:",
"Интервал, мин:": "Interval, min:",
"Сброс после N провалов:": "Reset after N failures:",
"Защита от ложного сброса при «обвале связи»": "Protection against a false reset during a “connectivity outage”",
"Контрольный сайт (НЕ блокируется — если открывается, значит связь есть и провалы целевых = блокировка, сброс выполняется):": "Control site (NOT blocked — if it opens, connectivity is there and failures of the targets = a block, the reset is performed):",
"Пусто = считать обвалом любое падение всех сайтов (старое поведение). Если у вас бывает, что все целевые блокируются разом — оставьте контрольный сайт, и сброс сработает.": "Empty = treat any failure of all sites as an outage (the old behaviour). If it happens that all targets are blocked at once — keep a control site, and the reset will fire.",
"Автоподбор, когда сайт перестал открываться:": "Auto search when a site stops opening:",
"подобрать и предложить": "find and suggest",
"подобрать и применить с проверкой": "find and apply with a check",
"Подбор идёт в песочнице (обход остальной сети не трогается), кандидаты из памяти подбора — первыми. Найденная стратегия заменяет текущую; при «применить» она остаётся, только если сайт открылся и ничего из открывавшегося не перестало (и только если текущая стратегия — один профиль; иначе предложит).": "The search runs in a sandbox (the bypass of the rest of the network isn't touched), candidates from the search memory go first. The found strategy replaces the current one; with “apply” it stays only if the site opened and nothing that was opening stopped (and only if the current strategy is a single profile; otherwise it suggests).",
"Один сайт — не чаще раза в, ч:": "One site — at most once every, h:",
"Выберите хотя бы один сайт для проверки": "Select at least one site to check",
"Пока ничего не выучено. «Автоподбор» — это стратегия типа": "Nothing learned yet. “Auto search” is a strategy of type",
": nfqws2 сам перебирает приёмы для каждого сайта и запоминает рабочий (память переживает перезагрузку роутера).": ": nfqws2 cycles through techniques for each site by itself and remembers the working one (the memory survives a router reboot).",
"Как включить автоподбор:": "How to enable auto search:",
"Нажмите кнопку ниже — список отфильтруется по авто-стратегиям.": "Press the button below — the list will be filtered to auto strategies.",
"Выберите любую «… (circular)» и нажмите «Применить».": "Choose any “… (circular)” and press “Apply”.",
"Открывайте заблокированные сайты — здесь начнут появляться выученные стратегии по доменам.": "Open blocked sites — learned strategies by domain will start appearing here.",
"Показать авто-стратегии": "Show auto strategies",
"Альтернатива — разовый «Подбор стратегий» (вкладка «Подбор»): он один раз протестирует и применит лучшую. circular же подстраивается постоянно и сам.": "The alternative is a one-time “Strategy search” (the “Search” tab): it tests once and applies the best one. circular keeps adapting by itself.",
