"Это fake-TLS только для входящего соединения Telegram-клиента к локальному proxy (режим ee). Он не меняет TLS fingerprint исходящего WSS-соединения роутера до Telegram/Cloudflare.": "This is fake-TLS only for the incoming connection of the Telegram client to the local proxy (ee mode). It doesn't change the TLS fingerprint of the router's outgoing WSS connection to Telegram/Cloudflare.",
