"Используется публичный community pool. Для постоянной эксплуатации предпочтительнее собственный CF-домен: общий pool может быть перегружен или заблокирован.": "The public community pool is used. For permanent use your own CF domain is preferable: the shared pool may be overloaded or blocked.",
"Соединение идёт напрямую на IP датацентра Telegram (поле «DC IP» выше). Работает только если провайдер не блокирует этот диапазон IP целиком.": "The connection goes directly to the Telegram data center IP (the “DC IP” field above). Works only if the ISP doesn't block this IP range entirely.",
"Сначала прямое соединение с Telegram DC, затем Cloudflare community fallback. Передаётся": "First a direct connection to the Telegram DC, then the Cloudflare community fallback. Passed",
