"proxy.мойдомен.ру": "proxy.mydomain.com",
"Для custom-режима обязательно заполните это поле либо Worker справа. Community pool вынесен в отдельный режим. Требует домен, добавленный в Cloudflare с включённым проксированием (см.": "For custom mode fill in this field or the Worker on the right. The community pool is a separate mode. Requires a domain added to Cloudflare with proxying enabled (see",
