"Туннель": "Tunnel",
"Важно понимать:": "Important to understand:",
"при отказе этого WARP-туннеля (например, Cloudflare заблокирует WireGuard/ MASQUE-подсети WARP в вашей стране) вы одновременно потеряете и общий VPN через этот туннель, и обход блокировки Telegram — это одна и та же инфраструктура, а не независимый резерв. Если для вас важна отказоустойчивость именно Telegram-обхода, надёжнее держать отдельный CF-домен (режим выше) — он не зависит от состояния вашего WARP-туннеля.": "if this WARP tunnel fails (e.g. Cloudflare's WARP WireGuard/MASQUE subnets get blocked in your country), you lose both the general VPN through this tunnel and the Telegram bypass at the same time — it's the same infrastructure, not an independent backup. If the resilience of the Telegram bypass specifically matters to you, it is more reliable to keep a separate CF domain (the mode above) — it doesn't depend on the state of your WARP tunnel.",
