"Нажмите \"Проверить обновления\" для проверки.": "Press “Check for updates” to check.",
"Фоновая проверка": "Background check",
"Нет данных.": "No data.",
"Не удалось узнать последнюю версию: {0}. Проверьте доступ к api.github.com (или зеркало в «Настройках»).": "Could not find out the latest version: {0}. Check access to api.github.com (or the mirror in “Settings”).",
