"Проверка неполная — обновлений не найдено среди ответивших источников{0}": "The check is incomplete — no updates found among the sources that responded{0}",
"Все бинарники актуальны": "All binaries are up to date",
"Проверка невозможна: в Python не работает SSL": "The check is impossible: SSL doesn't work in Python",
