"Свой I1": "Custom I1",
"Какой трафик пускать в туннель": "Which traffic to send into the tunnel",
"Подсети через запятую": "Subnets, comma-separated",
"Keepalive, с": "Keepalive, s",
"Имя устройства в Cloudflare": "Device name in Cloudflare",
"не задано": "not set",
"Только для AmneziaWG/mihomo v3+.": "Only for AmneziaWG/mihomo v3+.",
"Последние настройки": "Recent settings",
"Подходящие значения уже выбраны — можно сразу жать «Сгенерировать».": "Suitable values are already selected — you can press “Generate” right away.",
