"внешний UDP, внутренний MASQUE": "outer UDP, inner MASQUE",
"Трафик сам в туннель не идёт: на странице": "Traffic doesn't go into the tunnel by itself: on the page",
"выберите методом": "choose as the method",
"(подписан «WARP-in-WARP: внутренний»). Маршрут в outer — это одиночный туннель.": "(labelled “WARP-in-WARP: inner”). A route into the outer one is a single tunnel.",
"Сначала установите usque на странице WARP/MASQUE — без него двойной туннель не поднять": "First install usque on the WARP/MASQUE page — the double tunnel can't be brought up without it",
