"WARP-in-WARP активен ({0})": "WARP-in-WARP is active ({0})",
"Для WARP-in-WARP нужен usque (MASQUE). Установите его на странице WARP/MASQUE.": "WARP-in-WARP needs usque (MASQUE). Install it on the WARP/MASQUE page.",
"Двойной MASQUE. По умолчанию usque использует H3/QUIC; H2/TCP можно включить в профиле usque.": "Double MASQUE. By default usque uses H3/QUIC; H2/TCP can be enabled in the usque profile.",
"MASQUE + MASQUE (двойной usque)": "MASQUE + MASQUE (double usque)",
"Внешний MASQUE маскирует трафик, внутренний AmneziaWG обеспечивает шифрование WireGuard.": "The outer MASQUE masks the traffic, the inner AmneziaWG provides WireGuard encryption.",
"Внешний AmneziaWG (UDP) + внутренний MASQUE. Используйте только если это действительно нужно: второй слой повышает latency.": "Outer AmneziaWG (UDP) + inner MASQUE. Use only if really needed: the second layer increases latency.",
"AmneziaWG + AmneziaWG — двойной WG-туннель. Доступен на странице AmneziaWG → WARP.": "AmneziaWG + AmneziaWG — a double WG tunnel. Available on the AmneziaWG → WARP page.",
"AWG + AWG (двойной AmneziaWG)": "AWG + AWG (double AmneziaWG)",
"по умолчанию H3/QUIC; режим H2/TCP:443 задаётся в конфиге usque. Второй слой не гарантирует невидимость для DPI.": "H3/QUIC by default; the H2/TCP:443 mode is set in the usque config. The second layer doesn't guarantee invisibility to DPI.",
"Внешний MASQUE + внутренний AmneziaWG (UDP). Даёт сочетание маскировки трафика и WG-шифрования.": "Outer MASQUE + inner AmneziaWG (UDP). Combines traffic masking and WG encryption.",
"Внешний AmneziaWG (UDP) + внутренний MASQUE. Альтернатива при проблемах с внешним MASQUE.": "Outer AmneziaWG (UDP) + inner MASQUE. An alternative when the outer MASQUE has problems.",
"Двойной AmneziaWG. Доступен на странице": "Double AmneziaWG. Available on the page",
"Транспорт usque": "usque transport",
"Auto — H3, затем H2 при подтверждённом сбое": "Auto — H3, then H2 on a confirmed failure",
"H2 внутри H2 запрещён. MASQUE + MASQUE остаётся экспериментальным: двойной слой увеличивает задержку и не делает внешний трафик невидимым для DPI.": "H2 inside H2 is not allowed. MASQUE + MASQUE remains experimental: the double layer increases latency and doesn't make outer traffic invisible to DPI.",
