"— флаг без значения": "is a flag without a value",
"не похоже на параметр nfqws2 (ожидается --флаг). Незакавыченный пробел в значении?": "doesn't look like an nfqws2 parameter (--flag expected). An unquoted space in a value?",
"неизвестный флаг «{0}» (nfqws2). Проверьте написание — legacy nfqws1 (--dpi-desync*) не поддерживается.": "unknown flag “{0}” (nfqws2). Check the spelling — legacy nfqws1 (--dpi-desync*) is not supported.",
"неизвестный флаг «": "unknown flag “",
"Проверьте написание — legacy nfqws1 (--dpi-desync*) не поддерживается.": "Check the spelling — legacy nfqws1 (--dpi-desync*) is not supported.",
"{0} требует значение ({1}=…)": "{0} requires a value ({1}=…)",
"требует значение (": "requires a value (",
"Есть приём (--lua-desync), но нет ни --filter-*, ни --payload — десинк применится ко всему трафику очереди. Ограничьте порт/протокол.": "There is a technique (--lua-desync), but neither --filter-* nor --payload — the desync will apply to all traffic in the queue. Limit the port/protocol.",
"Список доменов/IP не указан — стратегия применяется ко всему трафику на портах фильтра (исключения netrogat учитываются отдельно). Чтобы сузить — добавьте --hostlist=… или --hostlist-domains=…": "No domain/IP list is specified — the strategy applies to all traffic on the filter ports (netrogat exclusions are handled separately). To narrow it — add --hostlist=… or --hostlist-domains=…",
"UDP-фейк с пониженным TTL: ICMP «время жизни истекло» NAT роутера доставит клиенту, и Safari/iOS/macOS рвут QUIC (Chrome — нет). Мусорный QUIC Initial сервер отбросит и без TTL.": "A UDP fake with lowered TTL: the router's NAT delivers the ICMP “time exceeded” to the client, and Safari/iOS/macOS break QUIC (Chrome doesn't). The server discards a junk QUIC Initial even without TTL.",
"fake без blob=: lua бросит ошибку на первом пакете, и приём ничего не пошлёт. Укажите фейк: blob=fake_default_tls (TLS), fake_default_quic или fake_default_udp (UDP), fake_default_http (HTTP).": "fake without blob=: lua throws an error on the first packet, and the technique sends nothing. Specify a fake: blob=fake_default_tls (TLS), fake_default_quic or fake_default_udp (UDP), fake_default_http (HTTP).",
"tls_mod на blob=0x{0} — это не TLS ClientHello, модифицировать нечего: nfqws2 будет писать в лог «cannot apply tls mod. tls structure invalid» и слать blob без изменений. Уберите tls_mod= или возьмите TLS-фейк (fake_default_tls, tls_google).": "tls_mod on blob=0x{0} — this is not a TLS ClientHello, there is nothing to modify: nfqws2 will write “cannot apply tls mod. tls structure invalid” to the log and send the blob unchanged. Remove tls_mod= or use a TLS fake (fake_default_tls, tls_google).",
"tls_mod на blob=0x": "tls_mod on blob=0x",
"— это не TLS ClientHello,": "— this is not a TLS ClientHello,",
"модифицировать нечего: nfqws2 будет писать в лог «cannot apply": "there is nothing to modify: nfqws2 will write “cannot apply",
"tls mod. tls structure invalid» и слать blob без изменений.": "tls mod. tls structure invalid” to the log and send the blob unchanged.",
"Уберите tls_mod= или возьмите TLS-фейк (fake_default_tls, tls_google).": "Remove tls_mod= or use a TLS fake (fake_default_tls, tls_google).",
"Фейк маскируется только через tcp_ts: Windows по умолчанию не шлёт метки TCP, и фейк уйдёт серверу настоящим пакетом. Добавьте вторую маскировку (tcp_md5, ip_autottl, tcp_seq) или включите метки: netsh interface tcp set global timestamps=enabled": "The fake is masked only via tcp_ts: Windows doesn't send TCP timestamps by default, and the fake reaches the server as a real packet. Add a second masking (tcp_md5, ip_autottl, tcp_seq) or enable timestamps: netsh interface tcp set global timestamps=enabled",
"Фейк маскируется только через tcp_ack без tcp_ts_up: Linux-сервер стабильно отбрасывает его, лишь когда метка TCP идёт первой опцией (так всегда делал nfqws1, nfqws2 — нет). Добавьте tcp_ts_up.": "The fake is masked only via tcp_ack without tcp_ts_up: a Linux server reliably drops it only when the TCP timestamp is the first option (nfqws1 always did this, nfqws2 doesn't). Add tcp_ts_up.",
"Рекомендуемый порядок: фильтры → домены/IP → диапазон/payload → --lua-desync.": "Recommended order: filters → domains/IP → range/payload → --lua-desync.",
"Неизвестный флаг nfqws2. Возможно опечатка или это legacy nfqws1 (не поддерживается).": "Unknown nfqws2 flag. Perhaps a typo, or it is legacy nfqws1 (not supported).",
